import{_ as e,o as t,c as r,a3 as i}from"./chunks/framework.DkWcobGL.js";const _=JSON.parse('{"title":"iPad 常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ipad/faq.md","filePath":"guide/ipad/faq.md"}'),o={name:"guide/ipad/faq.md"};function d(n,a,l,s,h,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="ipad-常见问题" tabindex="-1">iPad 常见问题 <a class="header-anchor" href="#ipad-常见问题" aria-label="Permalink to &quot;iPad 常见问题&quot;">​</a></h1><h2 id="为什么侧栏或右侧信息的位置变了" tabindex="-1">为什么侧栏或右侧信息的位置变了？ <a class="header-anchor" href="#为什么侧栏或右侧信息的位置变了" aria-label="Permalink to &quot;为什么侧栏或右侧信息的位置变了？&quot;">​</a></h2><p>拾光会按窗口可用空间布局。点左上角的侧栏图标可展开图库分类，打开 <strong>更多操作 → 显示照片信息</strong> 可以恢复信息区。在较窄的窗口中，照片信息和快捷相簿会移到照片附近。</p><h2 id="为什么图库只显示少量照片" tabindex="-1">为什么图库只显示少量照片？ <a class="header-anchor" href="#为什么图库只显示少量照片" aria-label="Permalink to &quot;为什么图库只显示少量照片？&quot;">​</a></h2><p>检查当前相簿或媒体筛选。系统只授予有限访问时，可从图库顶部 <strong>仅限所选照片 · 管理访问权限</strong> 添加照片，或到 iPad 系统设置调整拾光的权限。</p><h2 id="照片放大后滑动为什么不整理" tabindex="-1">照片放大后滑动为什么不整理？ <a class="header-anchor" href="#照片放大后滑动为什么不整理" aria-label="Permalink to &quot;照片放大后滑动为什么不整理？&quot;">​</a></h2><p>放大后拖动用于查看照片局部。缩回适合窗口即可继续滑动。也可点一下照片显示底部整理按钮。</p><h2 id="哪些操作会同步" tabindex="-1">哪些操作会同步？ <a class="header-anchor" href="#哪些操作会同步" aria-label="Permalink to &quot;哪些操作会同步？&quot;">​</a></h2><p>归类、收藏和最终删除会写回 Apple「照片」图库，跟随系统的 iCloud 照片设置。保留标记、待删除队列、统计和显示选项保存在当前 iPad。</p>',9)])])}const u=e(o,[["render",d]]);export{_ as __pageData,u as default};
